  onPut(key: any, now?: number): void
  onAccess(key: any, now?: number): void
  evict(entries: Map<any, any>): any | undefined
}
class LRU implements EvictionPolicy { /* ... */ }
class LFU implements EvictionPolicy { /* ... */ }
